#!/usr/bin/env python3
"""Test actual Gun Game equip/unit add/drop/delete with mocked allocator/gates.
No duplicated production transaction; --baseline-file permits a private negative control.
"""
import argparse,pathlib,re,subprocess,sys,tempfile
p=argparse.ArgumentParser();p.add_argument('--m32',action='store_true');p.add_argument('--sanitizers',action='store_true');p.add_argument('--cc',default='gcc');p.add_argument('--baseline-file',type=pathlib.Path);args=p.parse_args()
root=pathlib.Path(__file__).resolve().parents[1]
def extract(text,name):
    match=re.search(r'^(?:static\s+)?(?:void|boolean|short)\s+'+re.escape(name)+r'\([^;]*?\)\s*\{',text,re.M)
    if not match:raise RuntimeError('Production definition not found: '+name)
    start=match.start();brace=text.index('{',start);depth=1;index=brace+1
    while depth:
        if text[index]=='{':depth+=1
        elif text[index]=='}':depth-=1
        index+=1
    return text[start:index]+'\n'
units=(root/'source/units/units.c').read_text()
mode=(args.baseline_file or root/'port/linux/game/match_rules.c').read_text()
PREFIX='#define _unit_control_weapon_primary_trigger_bit 0\n#include <assert.h>\n#include <stdio.h>\n#include <string.h>\n#include "gun_game_progression.h"\ntypedef int boolean;\n#define TRUE 1\n#define FALSE 0\n#define NONE (-1)\n#define MAXIMUM_WEAPONS_PER_UNIT 4\n#define TEST_FLAG(x,b) ((x)&(1u<<(b)))\nenum{_game_connection_network_client=1,_unit_grenade_human_fragmentation=0,_unit_grenade_covenant_plasma=1,_unit_add_weapon_normal=0,_unit_add_weapon_starting=1,_unit_add_weapon_replace=2,_object_type_weapon=3,_object_connected_to_map_bit=0,_object_invisible_bit=1};\nstruct object_datum{struct{int flags;int type;long parent_object_index;}object;};\nstruct weapon_datum{long definition_index;struct{int flags;int type;long parent_object_index;}object;};\nstruct unit_datum{long definition_index;struct{int current_weapon_index,desired_weapon_index;long weapon_object_indices[4];int weapon_last_used_at_game_time[4];int grenade_counts[2],desired_grenade_index;unsigned control_flags;}unit;};\nstruct unit_definition{int unused;};struct player_datum{long unit_index;};struct object_placement_data{long tag;};\nstatic struct unit_datum u;static struct player_datum p;static struct unit_definition ud;static struct weapon_datum weapons[64];static struct gun_game_progression gun_game_players[2];static int allocated,allowed,connected,use,pickup,putaway,client,exists;static int deleted[64],checks;static char message[160];\nstatic struct unit_datum*unit_get(long i){assert(i==0);return &u;}\nstatic struct unit_datum*unit_try_and_get(long i){return i==0&&exists?&u:NULL;}\nstatic struct player_datum*player_get(long i){assert(i==0);return &p;}\nstatic struct weapon_datum*weapon_get(long i){assert(i>=0&&i<64);return &weapons[i];}\nstatic struct object_datum*object_get(long i){return (struct object_datum*)&weapons[i].object;}\nstatic struct object_datum*object_try_and_get(long i){return i>=0&&i<64&&!deleted[i]?(struct object_datum*)&weapons[i].object:NULL;}\nstatic struct unit_definition*unit_definition_get(long i){(void)i;return &ud;}\nstatic boolean match_rules_weapon_allowed_for_unit(long i,long tag){(void)i;(void)tag;return allowed;}\nstatic boolean unit_can_use_weapon(long i,long w){(void)i;(void)w;return use;}\nstatic boolean game_engine_picking_up(long i,long w){(void)i;(void)w;return pickup;}\nstatic void object_delete(long i){assert(i>=0&&i<64);deleted[i]++;}\nstatic void object_disconnect_from_map(long i){weapons[i].object.flags&=~1;}\nstatic void object_set_visibility(long i,boolean visible){(void)i;(void)visible;}\nstatic void item_in_unit_inventory(long w,long i){weapons[w].object.parent_object_index=i;}\nstatic short unit_weapon_next_index(long i,short start,int direction){(void)i;(void)direction;for(int n=1;n<=4;n++){int slot=(start+n+4)%4;if(u.unit.weapon_object_indices[slot]!=NONE)return slot;}return NONE;}\nstatic void player_control_set_desired_weapon(long i,short slot){(void)i;u.unit.desired_weapon_index=slot;}\nstatic void error(int level,const char*fmt,...){(void)level;(void)fmt;}\n#define _error_silent 0\nstatic const char*tag_get_name(long tag){(void)tag;return "fixture";}\nstatic long unit_get_current_weapon_index(long i){(void)i;int k=u.unit.current_weapon_index;return k>=0&&k<4?u.unit.weapon_object_indices[k]:NONE;}\nstatic boolean weapon_put_away(long i,boolean immediate){(void)i;(void)immediate;return putaway;}\nstatic void first_person_weapon_message_from_unit(long i,int msg){(void)i;(void)msg;}\nstatic void unit_drop_item(long i,long w){(void)i;weapons[w].object.parent_object_index=NONE;}\nstatic boolean weapon_can_be_fired(long i){(void)i;return TRUE;}\nstatic int game_connection(void){return client;}\nstatic boolean network_game_distributed_client(void){return FALSE;}\nstatic int gun_game_bind_player(long i){return i==0?0:-1;}\nstatic long gun_game_weapon_definition(int stage){(void)stage;return connected?100:NONE;}\nstatic void set_message(const char*m){snprintf(message,sizeof(message),"%s",m);}\nstatic void object_placement_data_new(struct object_placement_data*d,long tag,long parent){(void)parent;d->tag=tag;}\nstatic long object_new(struct object_placement_data*d){if(!allocated)return NONE;weapons[20].definition_index=d->tag;weapons[20].object.type=_object_type_weapon;weapons[20].object.flags=1;weapons[20].object.parent_object_index=NONE;return 20;}\n'
CHECKS='#define CHECK(x) do{if(!(x)){fprintf(stderr,"FAIL %s line%d\\n",#x,__LINE__);return 1;}checks++;}while(0)\nstatic void reset(void){memset(&u,0,sizeof(u));memset(weapons,0,sizeof(weapons));memset(deleted,0,sizeof(deleted));for(int k=0;k<4;k++)u.unit.weapon_object_indices[k]=NONE;u.unit.weapon_object_indices[1]=10;u.unit.current_weapon_index=1;u.unit.desired_weapon_index=1;weapons[10].object.type=3;weapons[10].object.parent_object_index=0;p.unit_index=0;exists=allocated=allowed=connected=use=pickup=putaway=1;client=0;gun_game_progression_clear(&gun_game_players[0]);gun_game_progression_bind(&gun_game_players[0],0);}\nint main(void){\n reset();allocated=0;CHECK(!gun_game_equip_player_stage(0));CHECK(u.unit.weapon_object_indices[1]==10&&!deleted[10]&&u.unit.desired_weapon_index==1);\n reset();allowed=0;CHECK(!gun_game_equip_player_stage(0));CHECK(deleted[20]==1&&!deleted[10]&&u.unit.weapon_object_indices[1]==10&&u.unit.desired_weapon_index==1);\n reset();use=0;CHECK(!gun_game_equip_player_stage(0));CHECK(deleted[20]==1&&!deleted[10]&&u.unit.current_weapon_index==1&&u.unit.desired_weapon_index==1);\n reset();pickup=0;CHECK(!gun_game_equip_player_stage(0));CHECK(deleted[20]==1&&!deleted[10]&&u.unit.desired_weapon_index==1);\n reset();connected=0;CHECK(!gun_game_equip_player_stage(0));CHECK(!deleted[10]&&u.unit.desired_weapon_index==1);\n reset();putaway=0;CHECK(!gun_game_equip_player_stage(0));CHECK(!deleted[10]&&u.unit.weapon_object_indices[1]==10&&u.unit.current_weapon_index==1);CHECK(u.unit.desired_weapon_index==1);CHECK(deleted[20]==1);CHECK(u.unit.weapon_object_indices[0]==NONE);\n reset();u.unit.weapon_object_indices[3]=11;weapons[11].object.parent_object_index=0;putaway=0;CHECK(!gun_game_equip_player_stage(0));CHECK(!deleted[10]&&!deleted[11]&&u.unit.weapon_object_indices[3]==11);CHECK(u.unit.current_weapon_index==1&&u.unit.desired_weapon_index==1&&deleted[20]==1);\n reset();for(int k=0;k<4;k++){u.unit.weapon_object_indices[k]=10+k;weapons[10+k].object.parent_object_index=0;}CHECK(!gun_game_equip_player_stage(0));for(int k=0;k<4;k++)CHECK(u.unit.weapon_object_indices[k]==10+k&&!deleted[10+k]);CHECK(u.unit.current_weapon_index==1&&u.unit.desired_weapon_index==1&&deleted[20]==1);\n reset();u.unit.weapon_object_indices[3]=11;weapons[11].object.parent_object_index=0;CHECK(gun_game_equip_player_stage(0));CHECK(u.unit.weapon_object_indices[0]==20&&u.unit.weapon_object_indices[1]==NONE&&u.unit.weapon_object_indices[3]==NONE);CHECK(deleted[10]==1&&deleted[11]==1&&!deleted[20]);CHECK(u.unit.desired_weapon_index==0&&u.unit.current_weapon_index==NONE);\n reset();u.unit.current_weapon_index=NONE;CHECK(gun_game_equip_player_stage(0));CHECK(deleted[10]==1&&u.unit.desired_weapon_index==0&&u.unit.weapon_object_indices[0]==20);\n reset();p.unit_index=NONE;exists=0;CHECK(gun_game_equip_player_stage(0));CHECK(!deleted[10]&&!deleted[20]);\n reset();client=1;CHECK(!gun_game_equip_player_stage(0));CHECK(!deleted[10]&&!deleted[20]);\n reset();struct gun_game_progression prior=gun_game_players[0];putaway=0;gun_game_progression_credit_kill(&gun_game_players[0],1);if(!gun_game_equip_player_stage(0))gun_game_progression_restore(&gun_game_players[0],&prior);CHECK(gun_game_progression_stage(&gun_game_players[0])==0);CHECK(u.unit.desired_weapon_index==1&&u.unit.weapon_object_indices[1]==10&&!deleted[10]);\n printf("%d extracted production transaction checks PASS\\n",checks);return 0;}\n'
body='\n'.join(extract(units,name) for name in ('unit_delete_all_weapons','unit_first_free_weapon_index','unit_add_weapon_to_inventory','unit_drop_current_weapon'))
body+=extract(mode,'gun_game_equip_player_stage')
with tempfile.TemporaryDirectory(prefix='halo-gun-game-transaction-') as tmp:
    source=pathlib.Path(tmp)/'test.c';binary=pathlib.Path(tmp)/'test';source.write_text(PREFIX+body+CHECKS)
    command=[args.cc,'-std=c11','-Wall','-Wextra','-Werror','-Wno-unused-function','-Wno-unused-variable','-Wno-implicit-fallthrough']
    if args.m32:command+=['-m32','-malign-double']
    if args.sanitizers:command+=['-fsanitize=address,undefined']
    command+=['-I'+str(root/'port/linux/game'),str(source),'-o',str(binary)]
    subprocess.run(command,check=True)
    result=subprocess.run([str(binary)],capture_output=True,text=True)
    sys.stdout.write(result.stdout);sys.stderr.write(result.stderr);sys.exit(result.returncode)
